import React, { useState, useRef, useEffect } from 'react';

const CameraProcessor = ({ colorblindType = 'protanopia', mode = 'simulate' }) => {
  const [streaming, setStreaming] = useState(false);
  const [error, setError] = useState(null);
  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const streamRef = useRef(null);
  const animationFrameRef = useRef(null);

  // Stop camera on unmount
  useEffect(() => {
    return () => stopCamera();
  }, []);

  // Redraw frame when colorblindType or mode changes
  useEffect(() => {
    if (streaming) {
      drawFrame();
    }
  }, [colorblindType, mode]);

  const applyColorFilter = (ctx, canvas) => {
    if (!ctx || !canvas) return;
    const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
    const data = imageData.data;

    for (let i = 0; i < data.length; i += 4) {
      const r = data[i];
      const g = data[i + 1];
      const b = data[i + 2];

      if (mode === 'simulate') {
        if (colorblindType === 'protanopia') {
          data[i] = Math.round(0.56667 * r + 0.43333 * g + 0 * b);
          data[i + 1] = Math.round(0.55833 * r + 0.44167 * g + 0 * b);
          data[i + 2] = Math.round(0 * r + 0.24167 * g + 0.75833 * b);
        } else if (colorblindType === 'deuteranopia') {
          data[i] = Math.round(0.625 * r + 0.375 * g + 0 * b);
          data[i + 1] = Math.round(0.7 * r + 0.3 * g + 0 * b);
          data[i + 2] = Math.round(0 * r + 0.3 * g + 0.7 * b);
        } else if (colorblindType === 'tritanopia') {
          data[i] = Math.round(0.95 * r + 0.05 * g + 0 * b);
          data[i + 1] = Math.round(0 * r + 0.433 * g + 0.567 * b);
          data[i + 2] = Math.round(0 * r + 0.475 * g + 0.525 * b);
        }
      } else if (mode === 'enhance') {
        if (colorblindType === 'protanopia' || colorblindType === 'deuteranopia') {
          data[i + 2] = Math.round(Math.min(255, b * 1.3));
        } else if (colorblindType === 'tritanopia') {
          data[i] = Math.round(Math.min(255, r * 1.3));
        }
      }
    }

    ctx.putImageData(imageData, 0, 0);
  };

  const drawFrame = () => {
    const video = videoRef.current;
    const canvas = canvasRef.current;
    if (!video || !canvas) return;

    const ctx = canvas.getContext('2d');
    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
    applyColorFilter(ctx, canvas);

    // Keep animation loop
    animationFrameRef.current = requestAnimationFrame(drawFrame);
  };

  const startCamera = async () => {
    const video = videoRef.current;
    const canvas = canvasRef.current;

    if (!video || !canvas) {
      setError('Video or canvas element not ready');
      return;
    }

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: false });
      streamRef.current = stream;
      video.srcObject = stream;

      video.onloadedmetadata = () => {
        canvas.width = video.videoWidth || 640;
        canvas.height = video.videoHeight || 480;

        video.play().then(() => {
          setStreaming(true);
          setError(null);
          drawFrame();
        }).catch(err => setError('Failed to play video: ' + err.message));
      };
    } catch (err) {
      setError('Camera access error: ' + err.message);
    }
  };

  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current);
    if (videoRef.current) videoRef.current.srcObject = null;
    setStreaming(false);
  };

  return (
    <div className="component-container">
      <h2>Live Camera Processor</h2>

      {error && <div style={{ color: 'red', marginBottom: '10px' }}>{error}</div>}

      <div
        className="upload-area"
        style={{
          textAlign: 'center',
          padding: '40px 20px',
          border: '2px dashed #443f3f',
          borderRadius: '8px',
          backgroundColor: '#fdfdfd',
          cursor: 'pointer',
        }}
        onClick={streaming ? stopCamera : startCamera}
      >
        {!streaming ? (
          <>
            <p style={{ fontSize: '16px', marginBottom: '10px' }}>Click to start your camera</p>
            <p style={{ fontSize: '14px', color: '#666' }}>Live camera feed will appear below</p>
          </>
        ) : (
          <p style={{ fontSize: '16px' }}>✓ Camera is active (click to stop)</p>
        )}
      </div>

      <div
        style={{
          display: 'flex',
          justifyContent: 'center',
          gap: '20px',
          marginTop: '20px',
        }}
      >
        {/* Original Feed */}
        <div>
          <p style={{ textAlign: 'center' }}>Original</p>
          <video
            ref={videoRef}
            style={{
              width: '320px',
              border: '2px solid #ddd',
              borderRadius: '8px',
            }}
            autoPlay
            playsInline
            muted
          />
        </div>

        {/* Filtered Feed */}
        <div>
          <p style={{ textAlign: 'center' }}>Filtered</p>
          <canvas
            ref={canvasRef}
            style={{
              width: '320px',
              border: '2px solid #ddd',
              borderRadius: '8px',
            }}
          />
        </div>
      </div>

      <div style={{ textAlign: 'center', marginTop: '20px' }}>
        <button
          className="button"
          style={{
            padding: '10px 20px',
            fontSize: '16px',
            borderRadius: '8px',
            border: 'none',
            backgroundColor: '#7a4caf',
            color: '#fff',
            cursor: 'pointer',
            transition: 'background-color 0.3s',
          }}
          onClick={streaming ? stopCamera : startCamera}
          onMouseEnter={e => (e.currentTarget.style.backgroundColor = '#6b45a0')}
          onMouseLeave={e => (e.currentTarget.style.backgroundColor = '#784caf')}
        >
          {streaming ? 'Stop Camera' : 'Start Camera'}
        </button>
      </div>
    </div>
  );
};

export default CameraProcessor;
